package co.com.operationalrequests.requests.infrastructure.adapter.out.messaging;
import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*; import co.com.operationalrequests.requests.application.port.out.PendingOutboxEvent; import java.time.*; import java.util.*; import java.util.concurrent.CompletableFuture; import org.apache.kafka.clients.producer.ProducerRecord; import org.junit.jupiter.api.Test; import org.mockito.ArgumentCaptor; import org.springframework.kafka.core.KafkaTemplate;
class KafkaEventPublisherAdapterTest { @Test void aggregateIdIsKafkaKeyAndMetadataAreHeaders()throws Exception{@SuppressWarnings("unchecked") KafkaTemplate<String,String> kafka=mock(KafkaTemplate.class);when(kafka.send(any(ProducerRecord.class))).thenReturn(CompletableFuture.completedFuture(null));var aggregate=UUID.randomUUID();var event=new PendingOutboxEvent(UUID.randomUUID(),aggregate,"SolicitudTomada",1,UUID.randomUUID(),"{\"ok\":true}",Instant.now(),0);new KafkaEventPublisherAdapter(kafka,"events.v1").publish(event);var captor=ArgumentCaptor.forClass(ProducerRecord.class);verify(kafka).send(captor.capture());ProducerRecord<?,?> record=captor.getValue();assertThat(record.key()).isEqualTo(aggregate.toString());assertThat(record.topic()).isEqualTo("events.v1");assertThat(record.headers().lastHeader("eventId")).isNotNull();} }
